# thickness_roundup_test.py (v10c, Roy ruling 2): test "drawn thickness = printed total rounded UP to the next whole inch" on the FILED track, every floor sheet A-100..A-104,
# every typed group P1,P2,P3,W1,W2,P5 (P4 printed "VARIES" so it has no rule to test). Input = wall_thickness_measured_vs_printed.csv (measured_in = the plan wall band's short side read from
# the v09b wall footprint polygons, i.e. what the plan draws). Tolerance for "equal to the rounded value": |measured - ceil(printed)| <= 0.02 in (a 0.01 in drift is the 10.99 vs 11 float read).
import csv, math, collections as C
rows = [r for r in csv.DictReader(open('wall_thickness_measured_vs_printed.csv', encoding='utf8')) if r['track'] == 'filed' and r['type_tag'] in ('P1', 'P2', 'P3', 'W1', 'W2', 'P5')]
TOL = 0.02
out = []; agg = C.OrderedDict()
for r in rows:
    pr = float(r['printed_total_in']); rule = math.ceil(pr - 1e-9); m = float(r['measured_in']); ok = abs(m - rule) <= TOL
    out.append(dict(sheet=r['sheet'], level=r['level'], type=r['type_tag'], wall_id=r['wall_id'], piece=r['piece'], piece_length_ft=r['piece_length_ft'], printed_in=pr, rule_ceil_in=rule, measured_in=m, fits_rule='yes' if ok else 'NO',
                    discriminates='yes' if pr != rule else 'no (printed already whole inch)'))
    k = (r['sheet'], r['level'], r['type_tag']); a = agg.setdefault(k, [0, 0, pr, rule, set()]); a[0] += 1; a[1] += ok; a[4].add(round(m, 2))
with open('thickness_roundup_test.csv', 'w', newline='', encoding='utf8') as f:
    w = csv.DictWriter(f, fieldnames=list(out[0].keys())); w.writeheader(); w.writerows(out)
L = ['# Whole-inch round-up test, FILED track (generated by thickness_roundup_test.py; method: measured_in from wall_thickness_measured_vs_printed.csv; tolerance %.2f in)' % TOL, '',
     '| sheet | level | type | printed in | rule (ceil) in | pieces | fit | measured values seen |', '|---|---|---|---|---|---|---|---|']
for (s, lv, t), (n, ok, pr, rule, ms) in agg.items():
    L.append('| %s | %s | %s | %s | %d | %d | %d | %s |' % (s, lv, t, pr, rule, n, ok, ', '.join(map(str, sorted(ms)))))
byt = C.defaultdict(lambda: [0, 0]); byl = C.defaultdict(lambda: [0, 0])
for o in out:
    for d, k in ((byt, o['type']), (byl, o['level'])): d[k][0] += 1; d[k][1] += o['fits_rule'] == 'yes'
L += ['', '## Per type (all floors): fit / pieces'] + ['- %s: %d / %d' % (k, v[1], v[0]) for k, v in sorted(byt.items())]
L += ['', '## Per floor: fit / pieces'] + ['- %s: %d / %d' % (k, v[1], v[0]) for k, v in sorted(byl.items())]
bad = [o for o in out if o['fits_rule'] == 'NO']
L += ['', '## Pieces that do NOT fit (%d)' % len(bad)] + ['- %s %s %s %s piece %s length %s ft: measured %s vs rule %s' % (o['sheet'], o['level'], o['type'], o['wall_id'][-6:], o['piece'], o['piece_length_ft'], o['measured_in'], o['rule_ceil_in']) for o in bad]
open('thickness_roundup_test.md', 'w', encoding='utf8').write('\n'.join(L) + '\n')
print('\n'.join(L))
